package app.xiaohe.assistant;

import org.json.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.regex.*;

/** Save display dates and date-only structure without changing original utterances. */
public final class AbsoluteDates {
  private static final Pattern RELATIVE=Pattern.compile("大后天|后天|前天|明天|今天|昨天|今晚|(?:上|下|本|这)周(?:[一二三四五六日天])?");
  private static final Pattern LOOSE=Pattern.compile("改天|找时间|时间未定|时间先不定|有空|上次|之前|以前|那天|下次");
  private static final Pattern HIDDEN=Pattern.compile("https?://[^\\s<>\"，。；]+|```[\\s\\S]*?```|`[^`]*`");
  private static final DateTimeFormatter DAY=DateTimeFormatter.ofPattern("yyyy年M月d日",Locale.SIMPLIFIED_CHINESE);
  private static final String[] DISPLAY={"dateNormalizedTitle","dateNormalizedContent","dateNormalizationAnchor","dateNormalizationSourceId","dateNormalizationVersion"};
  private AbsoluteDates(){}
  private static String masked(String text){Matcher m=HIDDEN.matcher(text);StringBuilder out=new StringBuilder(text);while(m.find())for(int i=m.start();i<m.end();i++)out.setCharAt(i,' ');return out.toString();}
  private static int left(String text,int index){for(int i=index-1;i>=0;i--)if("，,。；;！!？?\n".indexOf(text.charAt(i))>=0)return i+1;return 0;}
  private static int right(String text,int index){for(int i=index;i<text.length();i++)if("，,。；;！!？?\n".indexOf(text.charAt(i))>=0)return i;return text.length();}
  private static boolean literal(String text,int start,int end){String before=text.substring(left(text,start),start),after=text.substring(end,Math.min(text.length(),end+16));if(after.matches("(?s)^(科技|公司|集团|股份|有限|出版社|工作室|品牌).*"))return false;return !before.matches("(?s).*(上次|以前|之前|当时|原来说的|名字叫|名为|叫做|叫).{0,10}$")&&!before.matches("(?s).*(截图|图片|附件|资料|文件|文档|网页|链接|原文|录音|视频).*(里|中|上|写|说|提到|标注|显示).{0,12}$");}
  private static String hash(String value){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));char[] hex="0123456789abcdef".toCharArray();StringBuilder out=new StringBuilder(64);for(byte b:bytes)out.append(hex[(b&255)>>>4]).append(hex[b&15]);return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}

  public static JSONObject capture(JSONObject source)throws JSONException {
    if(source==null||!source.optString("role","user").equals("user"))return source;String text=source.optString("content"),digest=hash(text);JSONArray existing=source.optJSONArray("absoluteDates");
    if(source.optInt("absoluteDatesVersion")==1&&existing!=null){if(source.optString("absoluteDatesTextHash").equals(digest))return source;boolean lateVoice=source.optBoolean("absoluteDatesInputEmpty")&&source.optBoolean("recordedVoiceVerified")&&!text.isEmpty()&&text.equals(source.optString("voiceText"));if(!lateVoice)return source;}
    JSONObject anchor=source.optJSONObject("absoluteDateAnchor");if(anchor==null)anchor=TimeAnchor.source(source);source.put("absoluteDateAnchor",anchor);JSONObject frozen=frozen(source);JSONArray dates=new JSONArray();String clean=masked(text);Matcher m=RELATIVE.matcher(clean);
    while(m.find()){String raw=m.group();boolean own=literal(text,m.start(),m.end())&&(!source.has("voiceText")||source.optBoolean("recordedVoiceVerified")||!text.equals(source.optString("voiceText")));JSONObject entry=new JSONObject().put("raw",raw).put("index",m.start()).put("clause",text.substring(left(text,m.start()),right(text,m.end())).trim()).put("verifiedUser",own).put("zone",anchor.optString("zone")).put("capturedAt",anchor.optLong("capturedAt"));if(own){JSONObject time=TimeAnchor.resolve(raw,frozen,false,null,"future");entry.put("state",time.optString("state"));if(TimeAnchor.resolved(time)){long start=time.getLong("start");ZoneId zone=ZoneId.of(anchor.getString("zone"));LocalDate a=Instant.ofEpochMilli(start).atZone(zone).toLocalDate(),b=Instant.ofEpochMilli(time.getLong("end")-1).atZone(zone).toLocalDate();entry.put("date",a.toString()).put("dateStart",start).put("start",start).put("end",time.getLong("end")).put("precision",time.optString("precision")).put("dateText",DAY.format(a)+(a.equals(b)?"":"至"+DAY.format(b)+"期间"));}}else entry.put("state","reference_source_unknown");dates.put(entry);}
    source.put("absoluteDates",dates).put("absoluteDatesVersion",1).put("absoluteDatesTextHash",digest).put("absoluteDatesInputEmpty",text.isEmpty());return source;
  }
  public static JSONObject frozen(JSONObject source)throws JSONException {JSONObject copy=new JSONObject(source.toString()),anchor=source.optJSONObject("absoluteDateAnchor");if(anchor!=null)copy.put("capturedAt",anchor.optLong("capturedAt")).put("capturedZone",anchor.optString("zone"));return copy;}
  private static Map<String,String> mappings(JSONObject source)throws JSONException {capture(source);Map<String,String> out=new LinkedHashMap<>();JSONArray a=source==null?null:source.optJSONArray("absoluteDates");if(a!=null)for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);if(d.optBoolean("verifiedUser")&&!d.optString("dateText").isEmpty())out.put(d.getString("raw"),d.getString("dateText"));}return out;}
  private static boolean distinct(String raw,Map<String,String> map){Set<String> dates=new HashSet<>();Matcher words=RELATIVE.matcher(masked(raw));while(words.find()){String date=map.get(words.group());if(date!=null)dates.add(date);}return dates.size()>1;}
  private static String replace(String text,Map<String,String> map){String clean=masked(text);Matcher m=RELATIVE.matcher(clean);StringBuilder out=new StringBuilder();int at=0;while(m.find()){String date=map.get(m.group());if(date==null||!literal(text,m.start(),m.end()))continue;out.append(text,at,m.start()).append(date);at=m.end();}return out.append(text.substring(at)).toString();}
  public static String normalizeText(String text,JSONObject source)throws JSONException {if(text==null||source==null)return text;return replace(text,mappings(source));}

  /** Reject a model's user-date claim when it only occurs in a URL or quoted material. */
  public static JSONObject temporal(JSONObject request,JSONObject source,Store store,String direction)throws Exception {capture(source);String raw=request.optString("raw");Matcher words=RELATIVE.matcher(masked(raw));Map<String,String> allowed=mappings(source);if(request.optString("source","user").equals("user")&&distinct(raw,allowed))return new JSONObject().put("raw",raw).put("state","multiple_dates").put("precision","unknown").put("source","user").put("anchor",TimeAnchor.source(frozen(source)));while(request.optString("source","user").equals("user")&&words.find())if(!allowed.containsKey(words.group()))return new JSONObject().put("raw",raw).put("state","source_time_unknown").put("precision","unknown").put("source","user").put("anchor",TimeAnchor.source(frozen(source)));return TimeAnchor.normalize(request,frozen(source),store,direction);}

  private static String clause(JSONObject r,JSONObject source){String text=source.optString("content"),content=MemorySchema.normal(r.optString("content")),title=MemorySchema.normal(r.optString("title"));String best=null;int bestScore=0,ties=0;for(String part:text.split("[，,。；;！!？?\\n]")){String n=MemorySchema.normal(part);int score=content.length()>=2&&n.contains(content)?content.length():title.length()>=2&&n.contains(title)?title.length():0;if(score>bestScore){best=part;bestScore=score;ties=1;}else if(score>0&&score==bestScore)ties++;}if(bestScore>0&&ties==1)return best;if(LOOSE.matcher(masked(text)).find())return null;JSONArray a=source.optJSONArray("absoluteDates");int valid=0;String only=null;if(a!=null)for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d!=null&&d.optBoolean("verifiedUser")&&!d.optString("dateText").isEmpty()){valid++;only=d.optString("clause");}}return valid==1?only:null;}
  private static long knownDay(JSONObject t){return t==null?0:TimeAnchor.resolved(t)?t.optLong("start"):t.optLong("dateStart");}
  private static void decorate(JSONObject t,JSONObject source)throws JSONException {long instant=knownDay(t);if(instant<=0)return;JSONObject a=t.optJSONObject("anchor");String zone=a==null?TimeAnchor.zone(frozen(source)):a.optString("zone",TimeAnchor.zone(frozen(source)));ZoneId tz=ZoneId.of(zone);LocalDate date=Instant.ofEpochMilli(instant).atZone(tz).toLocalDate();String text=DAY.format(date);if(t.optString("precision").equals("week")&&t.optLong("end")>instant)text+="至"+DAY.format(Instant.ofEpochMilli(t.getLong("end")-1).atZone(tz).toLocalDate())+"期间";t.put("dateStart",date.atStartOfDay(tz).toInstant().toEpochMilli()).put("date",date.toString()).put("dateText",text);Map<String,String> map=mappings(source);if(!distinct(t.optString("raw"),map)){Matcher raw=RELATIVE.matcher(t.optString("raw"));while(raw.find())map.put(raw.group(),text);}t.put("normalizedRaw",replace(t.optString("raw"),map));}

  public static JSONObject annotate(JSONObject r,JSONObject source)throws JSONException {
    if(r==null||r.optBoolean("dateNormalizationSuppressed")||source==null)return r;capture(source);JSONObject t=r.optJSONObject("time");boolean external=t!=null&&!t.optString("source","user").equals("user");boolean plan=r.optString("kind").equals("intent")||r.optString("kind").equals("event")||r.optString("processing").equals("pending");
    boolean ownNote=r.optString("kind").equals("note")&&RELATIVE.matcher(masked(r.optString("title")+r.optString("content"))).find();if(!external&&!r.optBoolean("structuredReview")&&knownDay(t)<=0&&(t==null||t.optString("raw").isEmpty())&&(plan||ownNote)){String part=clause(r,source);if(part!=null){Map<String,String> allowed=mappings(source);Matcher words=RELATIVE.matcher(masked(part));boolean own=false;while(words.find())if(allowed.containsKey(words.group()))own=true;if(own&&!distinct(part,allowed)&&!LOOSE.matcher(masked(part)).find()){JSONObject fixed=TimeAnchor.resolve(masked(part),frozen(source),false,null,r.optString("eventState").equals("occurred")?"past":"future").put("raw",part.trim()).put("source","user").put("basis","按这条用户原话的时间和时区固定日期");if(knownDay(fixed)>0){r.put("time",fixed);t=fixed;}}else if(LOOSE.matcher(part).find()&&r.optString("kind").equals("intent"))r.put("time",TimeAnchor.resolve(part,frozen(source),false,null,"future").put("source","user"));}}
    if(t!=null)decorate(t,source);Map<String,String> map=external?new LinkedHashMap<>():mappings(source);if(knownDay(t)>0&&!r.optBoolean("structuredReview")&&!distinct(t.optString("raw"),map)){Matcher raw=RELATIVE.matcher(t.optString("raw"));while(raw.find())map.put(raw.group(),t.optString("dateText"));}
    String title=r.optString("title"),content=r.optString("content"),normalTitle=replace(title,map),normalContent=replace(content,map);if(plan&&!r.optBoolean("structuredReview")&&knownDay(t)>0){String date=t.optString("dateText");if(normalTitle.equals(title)&&!title.contains(date))normalTitle=date+" · "+title;if(normalContent.equals(content)&&!content.contains(date))normalContent=date+" · "+content;}
    if(!normalTitle.equals(title))r.put("dateNormalizedTitle",normalTitle);else r.remove("dateNormalizedTitle");if(!normalContent.equals(content))r.put("dateNormalizedContent",normalContent);else r.remove("dateNormalizedContent");if(!normalTitle.equals(title)||!normalContent.equals(content))r.put("dateNormalizationVersion",1).put("dateNormalizationSourceId",source.optString("id")).put("dateNormalizationAnchor",t!=null&&t.optJSONObject("anchor")!=null?t.optJSONObject("anchor"):source.optJSONObject("absoluteDateAnchor"));return r;
  }
  public static JSONObject reminder(JSONObject request,JSONObject source,Store store)throws Exception {JSONObject checked=temporal(request,source,store,"future");if(checked.optString("state").equals("source_time_unknown"))return checked;return TimeAnchor.reminder(request,frozen(source),store);}
  public static void clear(JSONObject r)throws JSONException {for(String key:DISPLAY)r.remove(key);r.remove("dateNormalizationFromSnapshot");r.put("dateNormalizationSuppressed",true);}
  public static void restore(JSONObject current,JSONObject snapshot){for(String key:DISPLAY){current.remove(key);if(snapshot.has(key))try{current.put(key,snapshot.get(key));}catch(JSONException e){throw new IllegalStateException(e);}}try{current.put("dateNormalizationSuppressed",true).put("dateNormalizationFromSnapshot",true);}catch(JSONException e){throw new IllegalStateException(e);}}
}
